--- /dev/null
+++ b/applicationlauncher/applicationlauncher.cpp
@@ -0,0 +1,65 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "applicationlauncher.h"
+
+#include <QDir>
+#include <QFile>
+#include <QFileInfo>
+#include <QStandardPaths>
+
+#include <KIO/ApplicationLauncherJob>
+#include <KIO/DesktopExecParser>
+#include <KLocalizedString>
+#include <KNotification>
+#include <KNotificationJobUiDelegate>
+
+#include <memory>
+
+namespace ApplicationLauncher
+{
+static bool isProgramMissing(const KService::Ptr &service)
+{
+    const QString binary = KIO::DesktopExecParser::executablePath(service->exec());
+    if (binary.isEmpty()) {
+        return false;
+    }
+    if (QDir::isRelativePath(binary)) {
+        return QStandardPaths::findExecutable(binary).isEmpty();
+    }
+    return !QFileInfo::exists(binary);
+}
+
+void start(KIO::ApplicationLauncherJob *job, const KService::Ptr &service)
+{
+    job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
+
+    const QString entryPath = service->entryPath();
+    const QString userApplicationsPath = QStandardPaths::writableLocation(QStandardPaths::ApplicationsLocation);
+    if (entryPath.startsWith(userApplicationsPath + QLatin1Char('/'))) {
+        auto description = std::make_shared<QString>();
+        QObject::connect(job, &KJob::description, job, [description](KJob *, const QString &title) {
+            *description = title;
+        });
+        // finished is emitted before result, which the delegate uses to show its own error
+        QObject::connect(job, &KJob::finished, job, [service, entryPath, description](KJob *job) {
+            if (!job->error() || job->error() == KJob::KilledJobError || !isProgramMissing(service)) {
+                return;
+            }
+            job->uiDelegate()->setAutoErrorHandlingEnabled(false);
+            const QString title =
+                description->isEmpty() ? QString() : i18nc("@title:notification %1 is a job name, e.g. Launching Firefox", "%1 (Failed)", *description);
+            KNotification *notification = KNotification::event(KNotification::Error, title, job->errorString());
+            KNotificationAction *removeAction = notification->addAction(i18nc("@action:button remove application entry", "Remove from Menu"));
+            QObject::connect(removeAction, &KNotificationAction::activated, notification, [entryPath] {
+                QFile::remove(entryPath);
+            });
+        });
+    }
+
+    job->start();
+}
+}
